import logging
from typing import Optional

# 模块级别logger
logger = logging.getLogger(__name__)


def process_data(data: dict) -> dict:
    """封装process_data调用"""
    try:
        logger.debug("Processing data")
        result = {}
        for key, value in data.items():
            result[key] = str(value).upper()
        return result
    except Exception as e:
        logger.error(f"Error processing data: {str(e)}")
        raise


def validate_input(value: str) -> bool:
    """封装validate_input调用"""
    try:
        logger.debug(f"Validating input: {value}")
        return len(value) > 0
    except Exception as e:
        logger.error(f"Error validating input: {str(e)}")
        raise


def validate_input_wrapper(value: str) -> bool:
    """validate_input的包装方法"""
    if not validate_input(value):
        raise ValueError(f"Invalid input: {value}")
    return True


class DataHandler:
    # 类级别的logger实例
    logger = logging.getLogger(__name__)

    def __init__(self, source: str):
        """类初始化方法添加日志记录"""
        self.source = source
        self.data = {}
        self.logger.info(f"DataHandler initialized with source: {source}")

    def _handle_exception(self, method_name: str, e: Exception) -> None:
        """统一的异常处理方法"""
        self.logger.error(f"Error in {method_name}: {str(e)}", exc_info=True)
        raise

    def load(self) -> bool:
        """加载数据"""
        try:
            self.logger.info(f"Loading data from source: {self.source}")
            # 验证输入
            validate_input_wrapper(self.source)
            # 调用validate_input
            if not validate_input(self.source):
                self.logger.warning(f"validate_input returned False for source: {self.source}")
                return False
            self.data = {"loaded": True, "source": self.source}
            self.logger.info("Data loaded successfully")
            return True
        except Exception as e:
            self._handle_exception("load", e)
            return False

    def transform(self, func) -> dict:
        """数据转换"""
        try:
            self.logger.info("Transforming data")
            # 调用process_data封装
            if self.data:
                processed = process_data(self.data)
                result = {k: func(v) for k, v in processed.items()}
            else:
                result = {}
            self.logger.info(f"Transform completed, result keys: {list(result.keys())}")
            return result
        except Exception as e:
            self._handle_exception("transform", e)
            return {}

    def save(self, path: str) -> bool:
        """保存数据"""
        try:
            self.logger.info(f"Saving data to path: {path}")
            # 验证输入
            validate_input_wrapper(path)
            # 调用validate_input
            if not validate_input(path):
                self.logger.warning(f"validate_input returned False for path: {path}")
                return False
            self.logger.info("Data saved successfully")
            return True
        except Exception as e:
            self._handle_exception("save", e)
            return False
